                { "sticker.L12", "Cangrejo de lado" }, { "sticker.L12.text", "Camina de lado y saluda con las dos pinzas. Por favor, no lo pises." },
                { "sticker.L12.hint", "Sobre la tercera poza de marea, pasado el castillo de arena." },
                { "sticker.L13", "Gaviota descarada" }, { "sticker.L13.text", "Ha robado tres patatas, dos bocadillos y un balón. Por ahora." },
                { "sticker.L13.hint", "Encima del muro alto detrás del trampolín." },
                { "sticker.L14", "Castillo de arena" }, { "sticker.L14.text", "Cinco torres, una bandera y un foso. Construido antes de que subiera la marea." },
                { "sticker.L14.hint", "Sobre la plataforma alta después del trampolín." },
                { "sticker.L15", "Cono" }, { "sticker.L15.text", "Naranja chillón, nunca se mueve y siempre estorba. Todo un profesional." },
                { "sticker.L15.hint", "Con luz de día entre las dos pasarelas cubiertas, encima de la plataforma elevada." },
                { "sticker.L16", "Excavadora" }, { "sticker.L16.text", "Excava antes del desayuno y después de comer. Le encantan los charcos." },
                { "sticker.L16.hint", "Encima de la primera cuesta, de donde salen rodando los tubos." },
                { "sticker.L17", "Grúa torre" }, { "sticker.L17.text", "Desde ahí arriba, toda la ciudad parece un juego de mesa." },
                { "sticker.L17.hint", "Justo encima del montacargas: súbete y salta." },
                { "sticker.L18", "Hormigonera" }, { "sticker.L18.text", "Da vueltas y más vueltas: hormigón para el nuevo patio del cole." },
                { "sticker.L18.hint", "En el tramo elevado entre los dos túneles." },
                { "sticker.L19", "Perro bueno" }, { "sticker.L19.text", "Te devolverá el balón. Algún día. Después de otra vuelta al parque." },
                { "sticker.L19.hint", "Encima del tramo del perro blanco: pica el balón y salta." },
                { "sticker.L20", "Fuente danzante" }, { "sticker.L20.text", "Los chorros bailan cada hora. Mete el balón y míralo volar." },
                { "sticker.L20.hint", "En lo más alto del chorro más alto de la fuente." },
                { "sticker.L21", "Columpios" }, { "sticker.L21.text", "¡Más alto, más alto! El mejor asiento del parque, si llegas el primero." },
                { "sticker.L21.hint", "Encima de la estructura para trepar." },
                { "sticker.L22", "Pato del estanque" }, { "sticker.L22.text", "Capitán del estanque. Acepta pan e ignora los balones." },
                { "sticker.L22.hint", "Sobre la fuente después del estanque, junto al trampolín." },
                { "sticker.L23", "La campana del cole" }, { "sticker.L23.text", "¡Din don! Lo lograste. Cada calle, cada pegatina, hasta el cole." },
                { "sticker.L23.hint", "Encima del muro alto después de la fuente y el trampolín." },
