                { "challenge.C01.goal", "¡Mantén el balón en el aire todo lo que puedas! Cuenta tu mejor racha de toques antes de que se acabe el tiempo." },
                { "challenge.C02.goal", "¡Dale con el balón a todos los carteles de las tiendas de la calle antes de que se acabe el tiempo!" },
                { "challenge.C03.goal", "Recorre el circuito lo más rápido que puedas: el balón va BAJO por debajo de las barras y ALTO por dentro de los aros." },
                { "challenge.C04.goal", "Hay ocho dianas escondidas por la obra. Dale a todas las que puedas: ¡algunas necesitan un chut fuerte!" },
                { "challenge.C05.goal", "Los toques definitivos. ¿Puedes dar 30 toques seguidos?" },
                { "guide.juggle.kick", "Arrastra un poco hacia ARRIBA desde CHUTA y suelta: el balón sube desde tu pie." },
                { "guide.juggle.touch", "Toca la pantalla libre (no un botón) cada vez que caiga cerca para volver a subirlo. Si toca el suelo, la racha empieza de nuevo." },
                { "guide.juggle.walk", "Mueve un poco la palanca para quedarte debajo del balón." },
                { "guide.targets.kick", "Arrastra desde CHUTA hacia una diana y suelta: cuanto más largo, más fuerte el chut. Unos puntos muestran por dónde irá." },
                { "guide.targets.walk", "Camina con la palanca para acercarte y para recoger el balón después de cada chut." },
                { "guide.targets.jump", "SALTA a la rampa, a las cajas y al palé que se mueve para apuntar mejor a las dianas altas." },
                { "guide.slalom.walk", "Regatea con la palanca: camina contra el balón para llevarlo, bajo, por debajo de las barras." },
                { "guide.slalom.slide", "Baja la palanca para deslizarte con el balón por debajo del paseo de tablas del final." },
                { "guide.slalom.kick", "Arrastra hacia arriba desde CHUTA para levantar el balón por dentro de cada aro." },
