                { "coach.slide.title", "Deslízate: baja la palanca" },
                { "coach.slide.text", "Baja la palanca al llegar: pasas por debajo con los pies por delante y el balón rueda contigo." },
                { "coach.kerb.title", "Bordillo: toca SALTO" },
                { "coach.kerb.text", "Toca SALTO para subir. Sigue conduciendo: el balón sube rebotando detrás de ti." },
                { "coach.stepup.title", "Escalón: súbelo y SALTA" },
                { "coach.stepup.text", "Sube el balón al escalón (arrastra un poco hacia arriba desde CHUTA) y toca SALTO para subir detrás." },
                { "coach.chip.title", "Muro: pásalo por encima y SALTA" },
                { "coach.chip.text", "Arrastra hacia arriba desde CHUTA hacia el otro lado y suelta para pasar el balón por encima. Luego toca SALTO para seguirlo." },
                { "coach.chiphigh.title", "Muro alto: bombéalo y doble salto" },
                { "coach.chiphigh.text", "Arrastra mucho hacia arriba desde CHUTA para bombear el balón. Luego toca SALTO y otra vez en el aire para pasar." },
                { "coach.gap.title", "Hueco: pásalo y SALTA" },
                { "coach.gap.text", "Arrastra hacia arriba desde CHUTA hacia el otro lado para pasar el balón. Luego toca SALTO (y otra vez en el aire si hace falta)." },
                { "coach.gapdouble.title", "Hueco grande: pásalo y doble salto" },
                { "coach.gapdouble.text", "Pasa el balón al otro lado (arrastra hacia arriba desde CHUTA). Luego toca SALTO y otra vez en el aire para llegar más lejos." },
                { "coach.crates.title", "Cajas: apártalas de un chut" },
                { "coach.crates.text", "Arrastra desde CHUTA hacia las cajas y suelta: un chut fuerte las tira. O pasa el balón por encima y SALTA detrás." },
                { "coach.car.title", "Coche aparcado: pásalo y súbete" },
                { "coach.car.text", "Primero pasa el balón por encima del coche (arrastra mucho hacia arriba desde CHUTA). Luego SALTA al capó y por encima del techo." },
                { "coach.highwall.title", "Escalón: sube, para y pásalo" },
                { "coach.highwall.text", "Sube el balón al escalón y SALTA detrás. Suelta la palanca para parar, pásalo por encima del muro y SALTA detrás." },
                { "coach.springboard.title", "Cama elástica: lleva el balón" },
                { "coach.springboard.text", "Lanza hacia arriba todo lo que cae en ella. Lleva el balón primero y súbete detrás: saltáis los dos bien alto." },
                { "coach.bounce.title", "Cama elástica: súbete y rebota" },
                { "coach.bounce.text", "El agua ya ha subido el balón al otro lado. Súbete a la cama elástica: te lanza bien alto a ti también." },
                { "coach.platform.title", "Plataforma móvil: pásalo y SALTA" },
                { "coach.platform.text", "Cuando se acerque, sube el balón (arrastra hacia arriba desde CHUTA). Luego toca SALTO para subirte detrás y cruzar en ella." },
                { "coach.lift.title", "Montacargas: sube el balón y sube" },
                { "coach.lift.text", "Cuando esté abajo, sube el balón (arrastra hacia arriba desde CHUTA). Luego SALTA detrás y sube con él." },
                { "coach.swing.title", "Columpio: pásalo y balancéate" },
                { "coach.swing.text", "Primero pasa el balón al otro lado (arrastra hacia arriba desde CHUTA). Luego SALTA al asiento cuando se acerque y salta al otro lado." },
                { "coach.gate.title", "Puerta cerrada: chuta al botón" },
                { "coach.gate.text", "Arrastra desde CHUTA hacia el botón y suelta. Dale con el balón y la puerta se abre." },
                { "coach.crossing.title", "Paso de cebra: espera al verde" },
                { "coach.crossing.text", "Muñeco rojo: suelta la palanca y espera en el bordillo. Verde: cruza con el balón. Parpadeando: ¡date prisa!" },
                { "coach.siteexit.title", "Entrada de obra: espera al GO" },
                { "coach.siteexit.text", "STOP: sale la excavadora, espera antes de las rayas. GO: cruza con el balón. GO parpadeando: ¡date prisa!" },
                { "coach.tide.title", "Marea: espera a que baje" },
                { "coach.tide.text", "Para antes de la arena mojada mientras sube el mar. Cuando el agua se retire, cruza rápido con el balón." },
                { "coach.dog.title", "Perro: pásalo por encima" },
                { "coach.dog.text", "Los perros persiguen los balones bajos. Arrastra hacia arriba desde CHUTA para pasar el balón por encima del perro y sigue." },
                { "coach.people.title", "Gente: pásalo o espera" },
                { "coach.people.text", "El balón rebota en la gente. Pásalo por encima (arrastra hacia arriba desde CHUTA) o suelta la palanca y espera un hueco." },
                { "coach.seagull.title", "Gaviotas: llévalo bajo" },
                { "coach.seagull.text", "Las gaviotas atacan el balón. Llévalo bajo y cerca, y chuta solo cuando haya pasado la gaviota." },
                { "coach.fountain.title", "Fuente: llévalo a los chorros" },
                { "coach.fountain.text", "Lleva el balón directo a los chorros: el agua lo lanza bien alto y por encima. Luego ve detrás." },
                { "coach.juggle1.title", "Paso 1: súbelo desde CHUTA" },
                { "coach.juggle1.text", "Arrastra un poco hacia ARRIBA desde CHUTA y suelta: el balón sube desde tu pie." },
                { "coach.juggle2.title", "Paso 2: toca para dar toques" },
                { "coach.juggle2.text", "Toca la pantalla libre (no un botón) cada vez que el balón caiga cerca. ¡Que no toque el suelo!" },
                { "coach.jugglemove.title", "Ponte debajo del balón" },
                { "coach.jugglemove.text", "Mueve un poco la palanca para ponerte debajo del balón y toca la pantalla cuando caiga." },
                { "coach.jugglefetch.title", "Ve a por el balón" },
                { "coach.jugglefetch.text", "Camina hasta el balón con la palanca y vuelve a subirlo desde CHUTA." },
                { "coach.aim.title", "Apunta desde CHUTA a una diana" },
                { "coach.aim.text", "Arrastra desde CHUTA hacia una diana y suelta. Cuanto más largo, más fuerte; los puntos muestran por dónde irá." },
                { "coach.targetfetch.title", "Ve a por el balón" },
                { "coach.targetfetch.text", "Camina hasta el balón con la palanca. SALTA a las rampas y las cajas para apuntar mejor a las dianas altas." },
                { "coach.low.title", "Puerta baja: por el suelo" },
                { "coach.low.text", "Solo conduce con la palanca: camina contra el balón para que ruede por debajo de la barra. Aquí no chutes." },
                { "coach.hoop.title", "Aro: pásalo por dentro" },
                { "coach.hoop.text", "Arrastra hacia arriba desde CHUTA hacia el aro y suelta para levantar el balón por dentro." },
                { "coach.finish.title", "Deslízate hasta la meta" },
                { "coach.finish.text", "Baja la palanca para deslizarte con el balón por debajo del paseo de tablas y llévalo a la portería." },
                // El recorrido guiado de los controles (UI/ControlsTour) y la página de controles (UI/ControlsGuide).
