                { "tour.nice", "¡Muy bien!" }, { "tour.tryIt", "¡Pruébalo ahora!" },
                { "tour.walk.title", "Caminar" },
                { "tour.walk", "Esta es tu palanca. Empújala a la derecha para avanzar con el balón y a la izquierda para volver. Suéltala para pararte." },
                { "tour.slide.title", "Deslizarse" },
                { "tour.slide", "Baja la palanca para deslizarte por debajo de las cosas. Abajo y a la derecha, hacia delante; abajo y a la izquierda, hacia atrás." },
                { "tour.jump.title", "Saltar" },
                { "tour.jump", "Toca SALTO para saltar. Mantenlo para subir más y tócalo otra vez en el aire para un doble salto." },
                { "tour.kick.title", "Chutar" },
                { "tour.kick", "Arrastra desde CHUTA hacia donde quieras mandar el balón y suelta. Cuanto más largo, más fuerte. Un toque rápido es un pase corto." },
                { "tour.touch.title", "Toque perfecto" },
                { "tour.touch", "Toca en cualquier otro sitio justo al alcanzar el balón para un toque perfecto. Toca cuando baje para hacer toques." },
                { "tour.pause.title", "Pausa" },
                { "tour.pause", "¿Un descanso? La pausa está aquí arriba. Puedes volver a ver todo esto cuando quieras en Pausa > Controles." },
                { "controls.title", "Controles" },
                { "controls.walk", "Empuja la palanca a la izquierda o a la derecha para caminar. Suéltala para pararte: al pararte controlas el balón." },
                { "controls.slide", "Baja la palanca para deslizarte con los pies por delante bajo barras y vallas. Inclínala a un lado al bajarla para elegir hacia dónde. O desliza hacia abajo." },
                { "controls.jump", "Toca SALTO para saltar y mantenlo para subir más. Tócalo otra vez en el aire para un doble salto. O desliza hacia arriba." },
                { "controls.kick", "Arrastra desde CHUTA hacia donde deba ir el balón y suelta: cuanto más largo, más fuerte. Toca para un pase rápido. Se pone verde cuando llegas al balón." },
                { "controls.touch", "Toca en cualquier otro sitio al alcanzar el balón para un toque perfecto, y cuando baje para hacer toques." },
                { "controls.leftHanded", "¿Eres zurdo? Activa los controles para zurdos en Ajustes para poner la palanca a la derecha." },
                { "controls.tour", "Ver el recorrido guiado" }, { "controls.tourSet", "Se verá en el próximo nivel" },
